    schema: skillplaneDatafnSchema,
    database: createCursorStableReadAdapter(input.database.adapter),
    ...(multiRegion ? { plugins: [multiRegion] } : {}),
    allowUnknownResources: false,
    debug: input.debug ?? false,
    rest: false,
