      }
      return { ok: true };

    case "file":
      if (typeof value !== "string") {
        return { ok: false, error: `expected file (string), got ${typeof value}` };
      }
      return { ok: true };

    case "json":
      if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
