export const temporal = time;

export function createTimezoneResolver(
  records: readonly Partial<DatafnTimezoneChangeRecord>[],
  options: { defaultTimezone?: string | (() => string | undefined) } = {},
): DatafnTemporalTimezoneResolver {
  const sorted = records
    .filter(
      (record): record is DatafnTimezoneChangeRecord =>
        typeof record.timezone === "string" &&
        typeof record.effectiveFrom === "number" &&
        Number.isFinite(record.effectiveFrom),
    )
    .sort((a, b) => a.effectiveFrom - b.effectiveFrom);

  return ({ instant }) => {
    let resolved: string | undefined;
    for (const record of sorted) {
      if (record.effectiveFrom <= instant) {
        resolved = record.timezone;
      } else {
        break;
      }
    }
    return resolved ?? resolveDefaultTimezone(options.defaultTimezone);
  };
}

export function timezoneChangeId(
  effectiveFrom: number,
  timezone: string,
  suffix = "",
): string {
  const safeTimezone = timezone.replace(/[^A-Za-z0-9_-]/g, "_");
  const safeSuffix = suffix ? `:${suffix.replace(/[^A-Za-z0-9_-]/g, "_")}` : "";
  return `${TIMEZONE_CHANGE_ID_PREFIX}:${effectiveFrom}:${safeTimezone}${safeSuffix}`;
}

export function ensureBuiltinTemporal(schema: DatafnSchema): DatafnSchema {
  const existing = schema.resources.find(
    (resource) => resource.name === TIMEZONE_CHANGE_RESOURCE_NAME,
  );

  if (existing) {
    validateBuiltinTimezoneChange(existing);
    return schema;
  }

  return {
    ...schema,
    resources: [...schema.resources, createBuiltinTimezoneChangeResource()],
  };
}

export function createTemporalPlugin(
  config: DatafnTemporalConfig = {},
): DatafnPlugin {
  return {
    name: "datafn-temporal",
    runsOn: ["client", "server"],
    beforeQuery(_ctx, query) {
      if (Array.isArray(query)) {
        return query.map((entry) =>
          isRecord(entry) ? normalizeTemporalQuery(entry, config) : entry,
        );
      }
      return isRecord(query) ? normalizeTemporalQuery(query, config) : query;
    },
  };
}

function createBuiltinTimezoneChangeResource(): DatafnResourceSchema {
  return {
    name: TIMEZONE_CHANGE_RESOURCE_NAME,
    version: 1,
    idPrefix: TIMEZONE_CHANGE_ID_PREFIX,
    fields: [
      { name: "id", type: "string", required: true },
      { name: "timezone", type: "string", required: true },
      { name: "effectiveFrom", type: "number", required: true },
      { name: "recordedAt", type: "number", required: true },
      { name: "source", type: "string", required: false },
    ],
    indices: ["id", "effectiveFrom", "timezone"],
    permissions: {
      read: { fields: ["id", "timezone", "effectiveFrom", "recordedAt", "source"] },
      write: { fields: ["id", "timezone", "effectiveFrom", "recordedAt", "source"] },
    },
  };
}

function validateBuiltinTimezoneChange(resource: DatafnResourceSchema): void {
  if (resource.version !== 1) {
    throw new Error(
      `Timezone registry resource version mismatch: expected 1, got ${resource.version}`,
    );
  }

  const fields = new Map(resource.fields.map((field) => [field.name, field]));
  const required = [
    ["id", "string", true],
    ["timezone", "string", true],
    ["effectiveFrom", "number", true],
    ["recordedAt", "number", true],
    ["source", "string", false],
  ] as const;

  for (const [name, type, isRequired] of required) {
    const field = fields.get(name);
    if (!field) {
      throw new Error(`Timezone registry resource is missing required field "${name}"`);
    }
    if (field.type !== type || field.required !== isRequired) {
      throw new Error(
        `Timezone registry field "${name}" is incompatible with the built-in temporal schema`,
      );
    }
  }
}

type TemporalHelperOptions = Omit<DatafnTemporalClause, "field" | "period">;
type TemporalGroupHelperOptions = Omit<DatafnTemporalClause, "field" | "groupBy"> & {
  alias?: string;
  output?: DatafnTemporalStorage;
};

function periodHelper(
  field: string,
  scale: DatafnTemporalScale,
  at: string | number | Date | undefined,
  options: TemporalHelperOptions,
): DatafnTemporalClause {
  return { field, ...options, period: { scale, ...(at !== undefined ? { at } : {}) } };
}

function groupHelper(
  field: string,
  scale: DatafnTemporalScale,
  options: TemporalGroupHelperOptions,
): DatafnTemporalClause {
  const { alias, output, ...rest } = options;
  return { field, ...rest, groupBy: { scale, alias, output } };
}

function resolveTemporalClauseDefaults(
  clause: DatafnTemporalClause,
  config: DatafnTemporalConfig,
): DatafnTemporalClause {
  return {
    ...clause,
    timezone: clause.timezone ?? resolveTemporalTimezone(config),
    storage: clause.storage ?? "unix-ms",
    weekStartsOn: clause.weekStartsOn ?? config.weekStartsOn ?? 1,
  };
}

function resolveTemporalTimezone(config: DatafnTemporalConfig): string {
  const timezone =
    typeof config.timezone === "function" ? config.timezone() : config.timezone;
  return timezone || "UTC";
}

function resolveTimezoneForInstant(input: {
  timezone: string | undefined;
  config: DatafnTemporalConfig;
  instant: number;
  field: string;
  resource?: string;
  record?: Record<string, unknown>;
  scale?: DatafnTemporalScale;
}): string {
  if (input.timezone && input.timezone !== "user") {
    return input.timezone;
  }
  const resolved = input.config.timezoneResolver?.({
    instant: input.instant,
    field: input.field,
    resource: input.resource,
    record: input.record,
    scale: input.scale,
  });
  return resolved || resolveTemporalTimezone(input.config);
}

function resolveDefaultTimezone(
  timezone: string | (() => string | undefined) | undefined,
): string | undefined {
  return typeof timezone === "function" ? timezone() : timezone;
}

function mergeTemporalFilters(
  filters: Record<string, unknown> | undefined,
  generated: Record<string, unknown>[],
): Record<string, unknown> {
  if (!filters || Object.keys(filters).length === 0) {
    return generated.length === 1 ? generated[0] : { $and: generated };
  }
  return { $and: [filters, ...generated] };
}

function getZonedParts(date: Date, timezone: string): DatafnTemporalDateParts {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: timezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  }).formatToParts(date);

  const values: Record<string, number> = {};
  for (const part of parts) {
    if (part.type !== "literal") {
      values[part.type] = Number(part.value);
    }
  }

  let hour = values.hour ?? 0;
  if (hour === 24) {
    hour = 0;
  }

  return {
    year: values.year,
    month: values.month,
    day: values.day,
    hour,
    minute: values.minute ?? 0,
    second: values.second ?? 0,
    millisecond: date.getUTCMilliseconds(),
  };
}

function invalidTemporalDateParts(): DatafnTemporalDateParts {
  return {
    year: NaN,
    month: NaN,
    day: NaN,
    hour: NaN,
    minute: NaN,
    second: NaN,
    millisecond: NaN,
  };
}

function zonedTimeToUtcMs(
  parts: {
    year: number;
    month: number;
    day: number;
    hour: number;
    minute: number;
    second: number;
    millisecond: number;
  },
  timezone: string,
): number {
  if (!Object.values(parts).every(Number.isFinite)) {
    return NaN;
  }
  const utcGuess = Date.UTC(
    parts.year,
    parts.month - 1,
    parts.day,
    parts.hour,
    parts.minute,
    parts.second,
    parts.millisecond,
  );
  if (!Number.isFinite(utcGuess)) {
    return NaN;
  }
  const first = utcGuess - getTimezoneOffsetMs(new Date(utcGuess), timezone);
  if (!Number.isFinite(first)) {
    return NaN;
  }
  return utcGuess - getTimezoneOffsetMs(new Date(first), timezone);
}

function getTimezoneOffsetMs(date: Date, timezone: string): number {
  if (!Number.isFinite(date.getTime())) {
    return NaN;
  }
  const parts = getZonedParts(date, timezone);
  const asUtc = Date.UTC(
    parts.year,
    parts.month - 1,
    parts.day,
    parts.hour,
    parts.minute,
    parts.second,
    parts.millisecond,
  );
  return asUtc - date.getTime();
}

function resolvePath(record: Record<string, unknown>, path: string): unknown {
  if (!path.includes(".")) {
    return record[path];
  }
  let current: unknown = record;
  for (const part of path.split(".")) {
    if (!isRecord(current)) {
      return undefined;
    }
    current = current[part];
  }
  return current;
}

function normalizeWeekStartsOn(value: number): number {
  if (!Number.isInteger(value)) {
    return 1;
  }
  return ((value % 7) + 7) % 7;
}

function isTemporalClause(value: unknown): value is DatafnTemporalClause {
  return isRecord(value) && typeof value.field === "string";
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
","export interface SortTerm {
  field: string;
  direction: "asc" | "desc";
}

export type SortInputTerm = string | SortTerm;

function isSortDirection(direction: string): direction is SortTerm["direction"] {
  return direction === "asc" || direction === "desc";
}

/**
 * Parse DFQL sort strings into structured sort terms.
 * Handles "field", "field:asc", "field:desc", "-field".
 * Returns [] for undefined or empty input.
 */
export function parseSortTerm(term: unknown): SortTerm {
  if (typeof term === "object" && term !== null && !Array.isArray(term)) {
    const field = (term as { field?: unknown }).field;
    const rawDirection = (term as { direction?: unknown }).direction;
    const direction = rawDirection === undefined ? "asc" : rawDirection;
    if (typeof field !== "string" || field.length === 0) {
      throw new Error("Invalid sort field");
    }
    if (typeof direction !== "string" || !isSortDirection(direction)) {
      throw new Error(`Invalid sort direction "${String(direction)}" for field "${field}"`);
    }
    return { field, direction };
  }
  if (typeof term !== "string" || term.length === 0) {
    throw new Error("Invalid sort term");
  }
  if (term.startsWith("-")) {
    if (term.length === 1) throw new Error("Invalid sort field");
    return { field: term.slice(1), direction: "desc" };
  }
  const colonIdx = term.indexOf(":");
  if (colonIdx !== -1) {
    const field = term.slice(0, colonIdx);
    const direction = term.slice(colonIdx + 1);
    if (!field) throw new Error("Invalid sort field");
    if (!isSortDirection(direction)) {
      throw new Error(`Invalid sort direction "${direction}" for term "${term}"`);
    }
    return { field, direction };
  }
  return { field: term, direction: "asc" };
}

export function parseSortTerms(sort: SortInputTerm[] | undefined): SortTerm[] {
  if (!sort || sort.length === 0) return [];
  return sort.map(parseSortTerm);
}

/**
 * Sort records by the given terms with a stable id tie-breaker.
 * Null values sort after non-null in ascending order (before in descending).
 */
export function sortRecords(
  records: Record<string, unknown>[],
  terms: SortTerm[],
): Record<string, unknown>[] {
  return [...records].sort((a, b) => {
    for (const term of terms) {
      const aVal = a[term.field];
      const bVal = b[term.field];

      if (aVal === bVal) continue;

      let cmp: number;
      if (aVal === null || aVal === undefined) {
        cmp = 1; // nulls after non-null in ascending
      } else if (bVal === null || bVal === undefined) {
        cmp = -1;
      } else if (typeof aVal === "string" && typeof bVal === "string") {
        cmp = aVal.localeCompare(bVal);
      } else if (typeof aVal === "number" && typeof bVal === "number") {
        cmp = aVal - bVal;
      } else {
        cmp = String(aVal).localeCompare(String(bVal));
      }

      if (cmp !== 0) return term.direction === "asc" ? cmp : -cmp;
    }

    // Stable id tie-breaker
    return String(a.id ?? "").localeCompare(String(b.id ?? ""));
  });
}
","export interface SelectToken {
  path: string[];
  baseName: string;
  directive: string | undefined;
}

/**
 * Parse a DFQL select token string into its structured components.
 * Examples: "id" → {path:["id"], baseName:"id", directive:undefined}
 *           "tags.*" → {path:["tags","*"], baseName:"tags", directive:"*"}
 *           "tasks.tags.*" → {path:["tasks","tags","*"], baseName:"tasks", directive:"tags.*"}
 */
export function parseSelectToken(token: string): SelectToken {
  const parts = token.split(".");
  const baseName = parts[0];
  const directive = parts.length > 1 ? parts.slice(1).join(".") : undefined;

  return { path: parts, baseName, directive };
}
","/**
 * Generic plugin hook runner (HKS-001)
 * Fail-closed for before hooks, fail-open for after hooks.
 */

import type { DatafnPlugin, DatafnHookContext } from "./types.js";

export interface HookError {
  code: string;
  message: string;
  details?: Record<string, unknown>;
}

export type BeforeHookResult<T> =
  | { ok: true; value: T }
  | { ok: false; error: HookError };

type AfterHookName = "afterQuery" | "afterMutation" | "afterSync";

function wrapError(err: unknown, pluginName: string, hookName: string): HookError {
  if (err && typeof err === "object") {
    const e = err as Record<string, unknown>;
    return {
      code: (e.code as string) || "INTERNAL",
      message: (e.message as string) || "Plugin error",
      details: { path: `plugins.${pluginName}.${hookName}`, ...((e.details as Record<string, unknown>) ?? {}) },
    };
  }
  return {
    code: "INTERNAL",
    message: String(err),
    details: { path: `plugins.${pluginName}.${hookName}` },
  };
}

/**
 * Run a before-style hook across plugins filtered by env.
 * Fail-closed: first error stops the chain and returns { ok: false, error }.
 * Each hook's return value (if defined) becomes the new payload.
 *
 * @param preArgs Optional args inserted before payload in hook call: hook(ctx, ...preArgs, payload)
 */
export async function runBeforeHook<T = unknown>(
  plugins: DatafnPlugin[],
  env: "client" | "server",
  hookName: keyof DatafnPlugin,
  ctx: DatafnHookContext,
  payload: T,
  preArgs: unknown[] = [],
): Promise<BeforeHookResult<T>> {
  let current = payload;
  const filtered = plugins.filter((p) => p.runsOn.includes(env));

  for (const plugin of filtered) {
    const hook = plugin[hookName] as ((...args: unknown[]) => Promise<unknown> | unknown) | undefined;
    if (!hook) continue;

    try {
      const result = await hook(ctx, ...preArgs, current);
      if (result !== undefined) current = result as T;
    } catch (err) {
      return { ok: false, error: wrapError(err, plugin.name, String(hookName)) };
    }
  }

  return { ok: true, value: current };
}

/**
 * Run an after-style hook across plugins filtered by env.
 * Fail-open: errors are logged but do not stop the chain.
 *
 * @param preArgs Optional args inserted before payload in hook call: hook(ctx, ...preArgs, payload, result)
 */
export async function runAfterHook(
  plugins: DatafnPlugin[],
  env: "client" | "server",
  hookName: AfterHookName,
  ctx: DatafnHookContext,
  payload: unknown,
  result: unknown,
  preArgs: unknown[] = [],
): Promise<unknown> {
  const filtered = plugins.filter((p) => p.runsOn.includes(env));
  let currentResult = result;

  for (const plugin of filtered) {
    const hook = plugin[hookName] as ((...args: unknown[]) => Promise<unknown> | unknown) | undefined;
    if (!hook) continue;

    try {
      const nextResult = await hook(ctx, ...preArgs, payload, currentResult);
      if (nextResult !== undefined) {
        currentResult = nextResult;
      }
    } catch (err) {
      console.error(`Plugin ${plugin.name}.${String(hookName)} error:`, err);
    }
  }

  return currentResult;
}
