  const temporalTable = registry.getTable(TIMEZONE_CHANGE_RESOURCE_NAME);
  const temporalApi = createTemporalApi({
    storage: resolvedStorage,
    temporalTable,
    clientId: config.clientId,
    getTimestamp,
    defaultTimezone: config.temporal?.timezone,
