export type CloneUpOptions = {
  resources?: string[];
  includeManyMany?: boolean;
  recordOperation?: "merge" | "replace" | "insert";
  batchSize?: number;
  maxRetries?: number;
  failFast?: boolean;
  clearChangelogOnSuccess?: boolean;
  setGlobalCursorOnSuccess?: boolean;
  pullAfter?: boolean;
  mutationIdPrefix?: string;
