export function resolveTemporalLocalTime(
  input: DatafnTemporalLocalTimeInput,
  timezone = "UTC",
): number {
  return zonedTimeToUtcMs(
    {
      year: input.year,
      month: input.month,
      day: input.day,
      hour: input.hour ?? 0,
      minute: input.minute ?? 0,
      second: input.second ?? 0,
      millisecond: input.millisecond ?? 0,
    },
    timezone,
  );
