      if (entry.operation === "insert" || entry.operation === "replace") {
        const defaults = defaultsByResource.get(entry.resource);
        if (defaults) {
          for (const [key, value] of defaults) {
            if (!(key in nextRecord)) {
              nextRecord[key] = cloneDefaultValue(value);
              changed = true;
