export const DATAFN_ERROR_CODES = [
  "SCHEMA_INVALID",
  "INVALID_CAPABILITY",
  "INVALID_CAPABILITY_CONFIG",
  "CAPABILITY_FIELD_COLLISION",
  "SYSTEM_FIELD_COLLISION",
  "CAPABILITY_DEPENDENCY",
  "DFQL_INVALID",
