  if (after && typeof after === "object" && !Object.keys(after).length) after = true;
  if (before === undefined && after !== undefined) {
    push(changes, {
      severity: direction === "input" ? "breaking" : "additive",
      code: "schema-added",
      path,
      message: `Schema added at ${path}`,
      after,
    });
