      severity: breaking ? "breaking" : "additive",
      code: tightened ? "constraint-tightened" : "constraint-relaxed",
      path: `${path}.${keyword}`,
      message: `${keyword} changed from ${oldValue ?? "unspecified"} to ${newValue ?? "unspecified"}`,
      before: oldValue,
      after: newValue,
    });
  }

