        const patternSchemas = matchingPatternSchemas(before, name);
        const fallbackSchemas = patternSchemas.length
          ? patternSchemas
          : [beforeAdditional as SchemaNode];
        fallbackSchemas.forEach((fallbackSchema, index) => diffSchema(
