interface McpApplication<Context = unknown> {
  fetch(
    request: Request,
    bindings: RuntimeBindings,
    context?: Context,
  ): Response | Promise<Response>;
}

interface ServiceBinding {
  fetch(request: Request): Response | Promise<Response>;
