  for (const tool of registry.definitions()) {
    const ui = tool.metadata?.ui as McpAppToolMetadata | undefined;
    if (!ui) continue;
    assertUiUri(ui.resourceUri);
    const resource = resources.get(ui.resourceUri);
    if (!resource) {
