      ui.visibility !== undefined &&
      (!Array.isArray(ui.visibility) ||
        !ui.visibility.length ||
        ui.visibility.some((value) => value !== "model" && value !== "app"))
    ) throw new McpFnValidationError(`Tool ${tool.name} has invalid MCP App visibility`);
  }
}
