function hasDefinitionAdditions<TContext>(
  options: McpFnServerDeclarationOptions<TContext>,
): boolean {
  return Boolean(
    options.tools?.length ||
    options.resources?.length ||
    options.resourceTemplates?.length ||
    options.prompts?.length
