    if (!scope.allowPublic) return false;
    if (scope.kind === "workspace-id" || scope.kind === "workspace-slug") {
      return true;
    }
    const result = await services.controlDatabase.pool.query(
      scope.kind === "skill-id" || scope.kind === "download-grant"
