function mcpToolErrorResponse(error: McpToolError): Response {
  if (
    error.code === "AUTHENTICATION_REQUIRED" ||
    error.code === "AUTH_SCOPE_REQUIRED"
  ) {
    return mcpAuthenticationResponse(
