const gql=`query($mcp: String!, $ski: String!, $old: String!) {
  mcp: issue(id: $mcp) {
    identifier title url description
    state { name type }
    team { name key }
    project { name }
    documents(first: 10) {
      nodes { id title url content issue { identifier url } }
      pageInfo { hasNextPage }
    }
    comments(first: 20) { nodes { id body } pageInfo { hasNextPage } }
  }
  ski: issue(id: $ski) {
    identifier title url description
    state { name type }
    team { name key }
    project { name }
    documents(first: 10) {
      nodes { id title url content issue { identifier url } }
      pageInfo { hasNextPage }
    }
    comments(first: 20) { nodes { id body } pageInfo { hasNextPage } }
  }
  old: issue(id: $old) {
    identifier title url
    state { name type }
    team { name key }
    project { name }
    comments(first: 20) { nodes { id body } pageInfo { hasNextPage } }
  }
}`;
