payload.input:
const gql=`query($mcp: String!, $ski: String!, $old: String!) {
  mcp: issue(id: $mcp) {
    identifier title url description state { name type } team { name key } project { name }
    documents(first: 10) { nodes { title url content issue { identifier url } } pageInfo { hasNextPage } }
    comments(first: 20) { nodes { body } pageInfo { hasNextPage } }
  }
  ski: issue(id: $ski) {
    identifier title url description state { name type } team { name key } project { name }
    documents(first: 10) { nodes { title url content issue { identifier url } } pageInfo { hasNextPage } }
    comments(first: 20) { nodes { body } pageInfo { hasNextPage } }
  }
  old: issue(id: $old) {
    identifier title url state { name type } team { name key }
    comments(first: 20) { nodes { body } pageInfo { hasNextPage } }
  }
}`;
const payload={query_or_mutation:gql,variables:{mcp:"MCP-4",ski:"SKI-19",old:"SKI-18"}};
const q=s=>"'" + s.replace(/'/g, "'\"'\"'") + "'";
const r=await tools.exec_command({
  cmd:`composio execute LINEAR_RUN_QUERY_OR_MUTATION -d ${q(JSON.stringify(payload))}`,
  workdir:"/Users/serro/orca/workspaces/skillplane/ski-16-adopt-ticket-protected-direct-regional-da",
  yield_time_ms:30000,
  max_output_tokens:30000
});
if (r.exit_code !== 0) { text(r.output); exit(); }
const parsed=JSON.parse(r.output);
const data=parsed.data.data;
function receipt(issue){
  const docs=issue.documents.nodes;
  return {
    identifier:issue.identifier,
    url:issue.url,
    team:issue.team,
    project:issue.project,
    state:issue.state,
    documentCount:docs.length,
    documents:docs.map(d=>({
      title:d.title,
      url:d.url,
      associatedIssue:d.issue?.identifier,
      backlinkPresent:d.content?.includes(issue.url) ?? false
    })),
    documentsHasMore:issue.documents.pageInfo.hasNextPage,
    visibleDocumentLinksPresent:issue.comments.nodes.some(c=>c.body.includes("Ideation & Product Rationale") && c.body.includes("Architecture & Delivery Plan")),
    partialWriteMarker:[issue.description,...issue.comments.nodes.map(c=>c.body)].filter(Boolean).some(s=>/association incomplete/i.test(s))
  };
}
text(JSON.stringify({
  mcp:receipt(data.mcp),
  ski:receipt(data.ski),
  old:{
    identifier:data.old.identifier,
    url:data.old.url,
    team:data.old.team,
    state:data.old.state,
    supersessionCommentPresent:data.old.comments.nodes.some(c=>c.body.includes("Superseded by")&&c.body.includes("MCP-4")&&c.body.includes("SKI-19")),
    commentsHasMore:data.old.comments.pageInfo.hasNextPage
  }
},null,2));

