import { consumeRateLimit } from "@skillplane/db";
import type { MiddlewareHandler } from "hono";
import type { ApiEnvironment } from "../context.js";
import { failure } from "../envelopes.js";

export function rateLimitRouteKey(path: string): string {
  if (path.startsWith("/api/v1/invitations/")) {
    return path.endsWith("/accept")
      ? "/api/v1/invitations/:token/accept"
      : "/api/v1/invitations/:token";
  }
  return path;
}

export function rateLimitMiddleware(): MiddlewareHandler<ApiEnvironment> {
  return async (context, next) => {
    const services = context.get("services");
    if (!services) {
      await next();
      return undefined;
    }
    if (
      services.deploymentRole === "cell" &&
      context.req.path.startsWith("/datafn/") &&
      context.req.header("x-datafn-route-ticket") !== undefined
    ) {
      // Public regional ingress already applies an IP DDoS limit. The private
      // DataFn server verifies the ticket and applies its workspace/actor limit.
      await next();
      return undefined;
    }
    const session = context.get("session");
    const servicePrincipal = context.get("servicePrincipal");
    const forwarded = context.req.header("cf-connecting-ip") ?? "unknown";
    const decision = await consumeRateLimit(
      services.controlDatabase.pool,
      `${rateLimitRouteKey(context.req.path)}:${session?.actorId ?? servicePrincipal?.actorId ?? forwarded}`,
      240,
      60,
    );
    context.header("x-ratelimit-remaining", String(decision.remaining));
    if (!decision.allowed) {
      context.header("retry-after", String(decision.retryAfterSeconds));
      return context.json(
        failure(context, "RATE_LIMITED", "Request rate limit exceeded"),
        429,
      );
    }
    await next();
    return undefined;
  };
}
import { AUTH_CSRF_HEADER, AUTH_SESSION_COOKIE, readCsrfToken } from "@skillplane/auth";
import { DomainError } from "@skillplane/domain";
import type { MiddlewareHandler } from "hono";
import type { ApiEnvironment, ApiServiceProvider } from "../context.js";
import { authenticateServicePrincipalRequest } from "../service-principal-auth.js";
import { ensurePersonalWorkspace } from "../tenancy.js";
import { initialWorkspaceRegionForRequest } from "../workspace-placement.js";

const SAFE_METHODS = new Set(["GET", "HEAD", "OPTIONS"]);

export function requiresPersonalWorkspace(path: string): boolean {
  return path.startsWith("/api/v1/") || path.startsWith("/datafn/");
}

export function enforceCookieCsrf(
  request: Request,
  hasSession: boolean,
  hasServicePrincipal: boolean,
): void {
  const url = new URL(request.url);
  if (
    !hasSession ||
    hasServicePrincipal ||
    SAFE_METHODS.has(request.method) ||
    !url.pathname.startsWith("/api/v1/")
  ) {
    return;
  }
  const cookie = request.headers.get("cookie") ?? "";
  const bearerWithoutSessionCookie =
    request.headers.get("authorization")?.startsWith("Bearer ") === true &&
    !cookie
      .split(";")
      .some((entry) => entry.trim().startsWith(`${AUTH_SESSION_COOKIE}=`));
  if (bearerWithoutSessionCookie) return;
  const cookieToken = readCsrfToken(request.headers.get("cookie"));
  const headerToken = request.headers.get(AUTH_CSRF_HEADER);
  if (!cookieToken || !headerToken || cookieToken !== headerToken) {
    throw new DomainError(
      "AUTH_CSRF_INVALID",
      "The request could not be verified",
      403,
    );
  }
}

export function authenticationMiddleware(
  getServices?: ApiServiceProvider,
): MiddlewareHandler<ApiEnvironment> {
  return async (context, next) => {
    if (!getServices || context.req.path.startsWith("/api/v1/health/")) {
      context.set("services", null);
      context.set("session", null);
      context.set("servicePrincipal", null);
      await next();
      return;
    }
    const services = await getServices(context.env);
    try {
      context.set("services", services);
      if (
        services.deploymentRole === "cell" &&
        context.req.path.startsWith("/datafn/") &&
        context.req.header("x-datafn-route-ticket") !== undefined
      ) {
        // DataFn verifies the ticket before deriving identity or executing a request.
        context.set("servicePrincipal", null);
        context.set("session", null);
        await next();
        return;
      }
      const serviceAuthentication = await authenticateServicePrincipalRequest(
        context.req.raw,
        services,
      );
      const servicePrincipal = serviceAuthentication?.principal ?? null;
      context.set("servicePrincipal", servicePrincipal);
      const session = servicePrincipal
        ? null
        : await services.auth.provider.authenticate(context.req.raw);
      context.set("session", session);
      if (session && requiresPersonalWorkspace(context.req.path)) {
        await ensurePersonalWorkspace(services.controlDatabase.pool, session, () =>
          initialWorkspaceRegionForRequest(context.req.raw, services, session.actorId),
        );
      }
      enforceCookieCsrf(context.req.raw, Boolean(session), Boolean(servicePrincipal));
      await next();
    } finally {
      try {
        await getServices.release?.(services);
      } catch {
        console.error(
          JSON.stringify({
            component: "api",
            event: "api.services.release.failed",
          }),
        );
      }
    }
  };
}
import { registerCompositionRoutes } from "./routes/composition.js";
import type { MiddlewareHandler } from "hono";
import { Hono } from "hono";
import type { ApiEnvironment, ApiServiceProvider } from "./context.js";
import { failure, success } from "./envelopes.js";
import { toApiError } from "./errors.js";
import { createReadinessProbe, type ReadinessProbe } from "./health.js";
import { authenticationMiddleware } from "./middleware/authentication.js";
import { authorizationMiddleware } from "./middleware/authorization.js";
import { observabilityMiddleware } from "./middleware/observability.js";
import { rateLimitMiddleware } from "./middleware/rate-limit.js";
import { requestIdMiddleware } from "./middleware/request-id.js";
import { securityMiddleware } from "./middleware/security.js";
import { registerInvitationRoutes } from "./routes/invitations.js";
import { registerAmendmentRoutes } from "./routes/amendments.js";
import { registerContextNoteRoutes } from "./routes/context-notes.js";
import { registerContextRoutes } from "./routes/contexts.js";
import { registerServicePrincipalRoutes } from "./routes/service-principals.js";
import { registerSkillRoutes } from "./routes/skills.js";
import { registerSkillSearchRoutes } from "./routes/search.js";
import { registerSkillVersionRoutes } from "./routes/skill-versions.js";
import { registerWorkspaceRoutes } from "./routes/workspaces.js";
import { registerReviewRoutes } from "./routes/reviews.js";
import { registerOAuthMetadataRoutes } from "./routes/oauth-metadata.js";
import { registerPublicStatsRoutes } from "./routes/public-stats.js";
import { registerAnalyticsRoutes } from "./routes/analytics.js";
import { registerAuditRoutes } from "./routes/audit.js";

export const MIDDLEWARE_ORDER = [
  "request-id",
  "security-headers",
  "observability",
  "authentication",
  "authorization",
  "rate-limit",
] as const;

type MiddlewareName = (typeof MIDDLEWARE_ORDER)[number];

export interface ApiOptions {
  readonly serviceName?: string;
  readonly readiness?: ReadinessProbe;
  readonly requestId?: () => string;
  readonly now?: () => Date;
  readonly getServices?: ApiServiceProvider;
  readonly middlewareObserver?: (name: MiddlewareName) => void;
  readonly oauthMetadata?: {
    readonly issuer: string;
    readonly resource: string;
  };
}

function observe(
  name: MiddlewareName,
  middleware: MiddlewareHandler<ApiEnvironment>,
  observer?: (name: MiddlewareName) => void,
): MiddlewareHandler<ApiEnvironment> {
  return async (context, next) => {
    observer?.(name);
    return middleware(context, next);
  };
}

export function createApiApp(options: ApiOptions = {}) {
  const app = new Hono<ApiEnvironment>();
  const serviceName = options.serviceName ?? "skillplane-app";
  const readiness = options.readiness ?? createReadinessProbe();
  const createRequestId = options.requestId ?? (() => crypto.randomUUID());
  const now = options.now ?? (() => new Date());

  app.use(
    "*",
    observe(
      "request-id",
      requestIdMiddleware(createRequestId),
      options.middlewareObserver,
    ),
  );
  app.use(
    "*",
    observe("security-headers", securityMiddleware(), options.middlewareObserver),
  );
  app.use(
    "*",
    observe("observability", observabilityMiddleware(), options.middlewareObserver),
  );
  app.use(
    "*",
    observe(
      "authentication",
      authenticationMiddleware(options.getServices),
      options.middlewareObserver,
    ),
  );
  app.use(
    "*",
    observe("authorization", authorizationMiddleware(), options.middlewareObserver),
  );
  app.use(
    "*",
    observe("rate-limit", rateLimitMiddleware(), options.middlewareObserver),
  );
  app.get("/api/v1/health/live", (context) =>
    context.json(
      success(context, {
        service: serviceName,
        status: "live",
        checkedAt: now().toISOString(),
      }),
    ),
  );

  app.get("/api/v1/health/ready", async (context) => {
    const result = await readiness(context.env);
    return context.json(
      success(context, {
        service: serviceName,
        status: result.ok ? "ready" : "not-ready",
        checkedAt: now().toISOString(),
        checks: result.checks,
      }),
      result.ok ? 200 : 503,
    );
  });

  registerOAuthMetadataRoutes(app, options.oauthMetadata);
  registerPublicStatsRoutes(app);
  registerAnalyticsRoutes(app);
  registerAuditRoutes(app);
  registerWorkspaceRoutes(app);
  registerInvitationRoutes(app);
  registerServicePrincipalRoutes(app);
  registerSkillSearchRoutes(app);
  registerSkillRoutes(app);
  registerSkillVersionRoutes(app);
  registerCompositionRoutes(app);
  registerAmendmentRoutes(app);
  registerReviewRoutes(app);
  registerContextRoutes(app);
  registerContextNoteRoutes(app);

  app.post("/api/v1/datafn/route", async (context) => {
    const bootstrap = context.get("services")?.datafnBootstrap;
    if (!bootstrap) {
      return context.json(
        failure(
          context,
          "DATAFN_DIRECT_DISABLED",
          "Direct DataFn transport is unavailable",
        ),
        404,
      );
    }
    return bootstrap(context.req.raw);
  });

  app.all("/auth/*", async (context) => {
    const services = context.get("services");
    if (!services) {
      return context.json(
        failure(context, "SERVICE_UNAVAILABLE", "Authentication is unavailable"),
        503,
      );
    }
    return services.auth.handle(context.req.raw);
  });

  app.all("/datafn/*", async (context) => {
    const services = context.get("services");
    if (!services) {
      return context.json(
        failure(context, "SERVICE_UNAVAILABLE", "Data access is unavailable"),
        503,
      );
    }
    return services.datafn.router.handle(context.req.raw);
  });

  app.notFound((context) =>
    context.json(
      failure(context, "ROUTE_NOT_FOUND", "The requested API route does not exist"),
      404,
    ),
  );

  app.onError((error, context) => {
    const response = toApiError(context, error);
    return context.json(response.body, response.status);
  });

  return app;
}
